"""Bake only manually authored floor lookdev to ordinary sRGB base-color PNG.
Source Tripo meshes/materials/images are never changed. Floor probe compares actual renders.
"""
import bpy,json,struct,hashlib
from pathlib import Path
from mathutils import Vector
import numpy as np
def bake_floor(out):
 scene=bpy.context.scene;floor=bpy.data.objects['Clean_Rectangular_Continuous_Floor'];old=floor.data.materials[0];states={o:o.hide_render for o in scene.objects if o.type=='MESH'};oldCamera=scene.camera;oldRes=(scene.render.resolution_x,scene.render.resolution_y);oldSamples=scene.cycles.samples;oldDenoise=scene.cycles.use_denoising;oldView=scene.view_settings.view_transform
 bpy.ops.mesh.primitive_plane_add(size=1,location=(0,0,10));helper=bpy.context.object;helper.name='TEMP_FLOOR_BAKE_ONLY';mat=old.copy();mat.name='TEMP_FLOOR_SOURCE_EMISSION';helper.data.materials.append(mat);nodes=mat.node_tree.nodes;links=mat.node_tree.links;tex=next(n for n in nodes if n.type=='TEX_COORD');mapping=next(n for n in nodes if n.type=='VECT_MATH');separate=nodes.new('ShaderNodeSeparateXYZ');links.new(tex.outputs['UV'],separate.inputs[0]);combine=nodes.new('ShaderNodeCombineXYZ');links.new(separate.outputs['X'],combine.inputs['X']);links.new(separate.outputs['Y'],combine.inputs['Y']);combine.inputs['Z'].default_value=1.;links.new(combine.outputs[0],mapping.inputs[0]);ramp=next(n for n in nodes if n.type=='VALTORGB');emission=nodes.new('ShaderNodeEmission');links.new(ramp.outputs['Color'],emission.inputs['Color']);output=next(n for n in nodes if n.type=='OUTPUT_MATERIAL');links.new(emission.outputs[0],output.inputs['Surface'])
 for o in states:o.hide_render=True
 helper.hide_render=False;cd=bpy.data.cameras.new('TEMP_FLOOR_PROBE_CAMERA');camera=bpy.data.objects.new('TEMP_FLOOR_PROBE_CAMERA',cd);scene.collection.objects.link(camera);camera.location=(0,0,12);camera.rotation_euler=(Vector((0,0,10))-camera.location).to_track_quat('-Z','Y').to_euler();cd.type='ORTHO';cd.ortho_scale=1.;scene.camera=camera;scene.render.resolution_x=512;scene.render.resolution_y=512;scene.cycles.samples=1;scene.cycles.use_denoising=False;scene.view_settings.view_transform='Standard';scene.render.filepath=str(out/'floor-source-probe.png');bpy.ops.render.render(write_still=True);sourceProbe=bpy.data.images.load(scene.render.filepath,check_existing=False);sourcePixels=np.asarray(sourceProbe.pixels[:],dtype=np.float32).reshape(-1,4).copy()
 image=bpy.data.images.new('Hybrid_Floor_BaseColor_2048',2048,2048,alpha=False);image.colorspace_settings.name='sRGB';target=nodes.new('ShaderNodeTexImage');target.image=image;nodes.active=target;target.select=True;bpy.ops.object.select_all(action='DESELECT');helper.select_set(True);bpy.context.view_layer.objects.active=helper;bpy.ops.object.bake(type='EMIT',margin=8,use_clear=True);folder=out/'textures';folder.mkdir(exist_ok=True);image.filepath_raw=str(folder/'kitchen-floor-basecolor-2048.png');image.file_format='PNG';image.save()
 # Reload the saved file: proof uses exported PNG decoding, not just the temporary bake buffer.
 png=bpy.data.images.load(image.filepath_raw,check_existing=False);png.colorspace_settings.name='sRGB';test=bpy.data.materials.new('TEMP_FLOOR_BAKED_PROBE');test.use_nodes=True;tn=test.node_tree.nodes;tl=test.node_tree.links;texture=tn.new('ShaderNodeTexImage');texture.image=png;emit=tn.new('ShaderNodeEmission');tl.new(texture.outputs['Color'],emit.inputs['Color']);tl.new(emit.outputs[0],tn.get('Material Output').inputs['Surface']);helper.data.materials[0]=test;scene.render.filepath=str(out/'floor-baked-probe.png');bpy.ops.render.render(write_still=True);bakedProbe=bpy.data.images.load(scene.render.filepath,check_existing=False);bakedPixels=np.asarray(bakedProbe.pixels[:],dtype=np.float32).reshape(-1,4).copy();delta=np.abs(sourcePixels[:,:3]-bakedPixels[:,:3]);metrics={'source':'actual procedural top-face color evaluated as emission','candidate':'actual saved PNG reloaded sRGB evaluated as emission','probePixels':len(delta),'savedPNGNormalizedRGB_MAE':float(delta.mean()),'savedPNGNormalizedRGB_Max':float(delta.max()),'savedPNGNormalizedRGB_P95':float(np.quantile(delta,.95)),'bakeResolution':[2048,2048],'roughness':.55,'metallic':0.,'lightingBaked':False,'normalMapAdded':False,'limits':'Procedural-floor lookdev bake only. Source Tripo maps unchanged. Probe compares512px rendered filtered samples, not mathematical identity.'};(out/'floor-bake-proof.json').write_text(json.dumps(metrics,indent=2))
 # Portable authored floor material: one image-driven Principled base color, scalar roughness.
 final=bpy.data.materials.new('Portable_Floor_BakedBaseColor');final.use_nodes=True;f=final.node_tree.nodes;texnode=f.new('ShaderNodeTexImage');texnode.image=png;p=f.get('Principled BSDF');final.node_tree.links.new(texnode.outputs['Color'],p.inputs['Base Color']);p.inputs['Roughness'].default_value=.55;p.inputs['Metallic'].default_value=0.;floor.data.materials[0]=final
 for loop in floor.data.loops:
  co=floor.data.vertices[loop.vertex_index].co;floor.data.uv_layers.active.data[loop.index].uv=(co.x+.5,co.y+.5)
 for o,v in states.items():o.hide_render=v
 bpy.data.objects.remove(helper,do_unlink=True);bpy.data.objects.remove(camera,do_unlink=True);scene.camera=oldCamera;scene.render.resolution_x,scene.render.resolution_y=oldRes;scene.cycles.samples=oldSamples;scene.cycles.use_denoising=oldDenoise;scene.view_settings.view_transform=oldView;png.pack()
 # Small portable proof: export only the authored12-triangle floor, not the6M source masters.
 bpy.ops.object.select_all(action='DESELECT');floor.select_set(True);bpy.context.view_layer.objects.active=floor;portable=out/'portable-floor.glb';bpy.ops.export_scene.gltf(filepath=str(portable),export_format='GLB',use_selection=True,export_materials='EXPORT',export_image_format='AUTO');raw=portable.read_bytes();size=struct.unpack_from('<I',raw,12)[0];g=json.loads(raw[20:20+size]);triangles=sum(g['accessors'][p['indices']]['count']//3 for m in g['meshes'] for p in m['primitives']);assert triangles==12 and len(g['meshes'])==1;assert g['materials'][0]['pbrMetallicRoughness'].get('baseColorTexture') is not None
 metrics['portableFloor']={'file':portable.name,'SHA256':hashlib.sha256(raw).hexdigest(),'triangles':triangles,'meshes':len(g['meshes']),'images':len(g.get('images',[])),'hasPBRBaseColorTexture':True,'scope':'Only manually authored floor exported; full master remains source-exact blend.'};(out/'floor-bake-proof.json').write_text(json.dumps(metrics,indent=2));return metrics
